module top_module(clk, rstn, leds);parameter width=8; 
  input clk; 
  input rstn; 
  output reg [width-1:0] leds; 
  always @(posedge clk, negedge rstn) begin 
  if (~rstn) 
  leds <= {width{1'b0}}; 
  else 
  leds <= leds + {{width-1{1'b0}}, 1'b1}; 
  end 
 endmodule

