                $display("  Got:      r_data_a=%h, r_data_b=%h",
                         r_data_a, r_data_b);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
    initial begin
        #1000000; // 1ms timeout
        $display("\nERROR: Simulation timeout!");
        $finish;
    end

    // Optional: Waveform dump for debugging
    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(0,clk, r_addr_a, r_addr_b, rst_n, w_addr, w_data, we, r_data_a, r_data_b);
    end

