description:
Design a clock divider that generates a slower clock signal (clk_o) from a faster input clock (clk_i). The module counts clock cycles and toggles the output clock signal every 1800 input clock cycles, effectively dividing the frequency by 3600. The counting process is reset when the reset signal (reset_n) is asserted low, setting both the output and the count register to zero. This functionality can be useful in applications where a slower clock is needed for timing control or synchronization.
module top_module(
	input clk_i,  
	input reset_n,  

	output reg clk_o
		);

code:
module top_module(
	input clk_i,  
	input reset_n,  

	output reg clk_o
		);reg [14:0] count;   


		always @ (posedge clk_i, negedge reset_n)			
			begin
				count <= count + 1;   
				if(!reset_n)
					begin
						clk_o <= 0;
						count <= 0;   
					end
				else
					if(count >= 1800)   
						begin   
							clk_o <= ~clk_o;	
                                                        count <= 0;	
						end
			end


endmodule

