description:
Design a circuit for reliable clock domain crossing of a single signal. The module synchronizes an input signal from clock domain A (SignalIn_clkA) to clock domain B (clkB) using a 4-stage synchronizer flip-flop configuration. The final output (SignalOut_clkB) reflects the state of the input signal after passing through the synchronization stages, reducing the risk of metastability and ensuring safe data transfer between the two clock domains.
module top_module(
    input SignalIn_clkA,
    input clkB,
    output SignalOut_clkB
);

code:
module top_module(
    input SignalIn_clkA,
    input clkB,
    output SignalOut_clkB
);reg [3:0] SyncA_clkB;
always @(posedge clkB) begin 
    SyncA_clkB[0] <= SignalIn_clkA;
    SyncA_clkB[1] <= SyncA_clkB[0];
    SyncA_clkB[2] <= SyncA_clkB[1];
    SyncA_clkB[3] <= SyncA_clkB[2];
end

assign SignalOut_clkB = SyncA_clkB[3];  
endmodule

