                exponent <= current_exponent;
                ready <= 1;
                current_exponent <= 0;
                current_value <= 1;
            end
        end
    end else begin
        exponent <= 0;
        ready <= 0;
        current_exponent <= 0;
        current_value <= 1;
    end
end

endmodule

