module top_module(
    input async_in,
    input sync_clk,
    output reg pulsed_out
    );reg edge_detect;
    always @(posedge async_in or posedge pulsed_out)
        if(pulsed_out)
            edge_detect <= 0;
        else
            edge_detect <= 1;

    always @(posedge sync_clk)
             pulsed_out <= edge_detect;

endmodule

