module top_module (
  input clk,
  input load,
  input [31:0] data,
  output reg [31:0] q
);

  // Intermediate register to hold the next state of the cells
  reg [31:0] next_q;

  // Combinational logic to calculate the next state based on the current state
  always @(*) begin
    integer i;
    for (i = 0; i < 32; i = i + 1) begin
      if (i == 0) begin
        // Left boundary: q[-1] is considered as 0
        next_q[i] = q[i] ^ q[i+1];
      end else if (i == 31) begin
        // Right boundary: q[32] is considered as 0
        next_q[i] = q[i-1];
      end else begin
        next_q[i] = q[i-1] & q[i+1] ^ q[i];
      end
    end
  end

  // Sequential logic to update the state on the rising edge of the clock
  always @(posedge clk) begin
    if (load) begin
      q <= data;
    end else begin
      q <= next_q;
    end
  end

endmodule

