module water_pump (
	input clk,
	input resetn,
	input start,
	output full);

	parameter OFF=0, FILLING=1, FULL=2;
	reg [1:0] state, next_state;
	reg [3:0] counter;

	always @(posedge clk) begin
		if (~resetn) state <= OFF;
		else state <= next_state;
	end

	always @(posedge clk) begin
		if (state == FILLING) counter <= counter + 1;
		else counter <= 0;
	end

	always_comb begin
		case (state)
			OFF: next_state = start ? FILLING : OFF;
			FILLING: next_state = (counter == 4'd7) ? FULL : FILLING;
			FULL: next_state = OFF;
			default: next_state = OFF;
		endcase
	end

	assign full = (state == FULL);
endmodule

