module d_flip_flop_async_reset(D, clk, reset, Q);
     input D;
     input clk;
     input reset;
     output Q;

     wire D_int, Q_int;

     not (resetn, reset);
     and (D_int, D, resetn);
     d_latch DL1 (.D(D_int), .clk(clk), .Q(Q_int));
     d_latch DL2 (.D(Q_int), .clk(~clk), .Q(Q));
endmodule

