always@ (posedge clk_in or posedge reset) begin
	if (reset== 1'b1)begin
		i=0;
		clk_out=0;
	end

	else begin
		i=i+1;
		if (i>=100000) begin
			clk_out=~clk_out;
			i=0;
		end
	end
end


endmodule

