description:
Design a two-input AND gate using basic logic gates. The module takes two inputs, A and B, inverts each of them, and then performs a logical OR operation on the inverted signals. Finally, it inverts the result of the OR operation to produce the AND gate output, Y. The design effectively demonstrates the functionality of an AND gate through the use of NOT and OR operations, adhering to De Morgan's theorem.
module top_module(
    input A,
    input B,
    output Y
);

code:
module top_module(
    input A,
    input B,
    output Y
);wire not_A, not_B, or_AB;

    // Invert A and B
    not #(1) not_A_inst (not_A, A);
    not #(1) not_B_inst (not_B, B);

    // OR the inverted A and B
    or #(1) or_AB_inst (or_AB, not_A, not_B);

    // Invert the output of the OR gate to get the AND output
    not #(1) not_Y_inst (Y, or_AB);

endmodule

