description:
Design a debouncing circuit for a button input to produce a stable output signal. The module uses a synchronous approach to filter out noise generated by mechanical bouncing of the button. It employs two D-type flip-flops (DFF1 and DFF2) along with a shift register (q_reg) to count the duration of stable input. When the button state remains unchanged for a certain number of clock cycles, the circuit asserts the debounce_output signal, which reflects the stable state of the button input. The implementation is parameterized for configurability, allowing adjustment of the debounce timing by changing the bit-width of the counter.
module top_module(
	input 			clk, button_in,				
	output debounce_output													
	);

code:
module top_module(
	input 			clk, button_in,				
	output debounce_output													
	);assign debounce_output = ~DB_out;

	reg 	DB_out;													
	parameter N = 11 ;		

	reg  [N-1 : 0]	q_reg;							
	reg  [N-1 : 0]	q_next;
	reg DFF1, DFF2;									
	wire q_add;											
	wire q_reset, n_reset;

assign n_reset =1'b1;


	assign q_reset = (DFF1  ^ DFF2);		
	assign  q_add = ~(q_reg[N-1]);			


	always @ ( q_reset, q_add, q_reg)
		begin
			case( {q_reset , q_add})
				2'b00 :
						q_next <= q_reg;
				2'b01 :
						q_next <= q_reg + 1;
				default :
						q_next <= { N {1'b0} };
			endcase
		end


	always @ ( posedge clk )
		begin
			if(n_reset ==  1'b0)
				begin
					DFF1 <= 1'b0;
					DFF2 <= 1'b0;
					q_reg <= { N {1'b0} };
				end
			else
				begin
					DFF1 <= button_in;
					DFF2 <= DFF1;
					q_reg <= q_next;
				end
		end


	always @ ( posedge clk )
		begin
			if(q_reg[N-1] == 1'b1)
					DB_out <= DFF2;
			else
					DB_out <= DB_out;
		end

	endmodule

