    output reg [1:0] Y,
    output reg V
);reg [1:0] Y_pipe1;
reg [1:0] Y_pipe2;
reg V_pipe1;
reg V_pipe2;

always @(posedge clk) begin
    Y_pipe2 <= Y_pipe1;
    Y_pipe1 <= Y;
    V_pipe2 <= V_pipe1;
    V_pipe1 <= V;

    if (A) begin
        Y <= 2'b00;
        V <= 1'b1;
