description:
Design a circuit that functions as a decoder for a 3-bit input, assigning specific 5-bit output codes based on the value of the input. The module maps input values from 0 to 4 to distinct 5-bit patterns defined by corresponding parameters, and it repeats the pattern for the input value 5. If an invalid input is received, the output defaults to zero.
module top_module(
    input [2:0] in_row,
    output reg [4:0] out_code
    );

code:
module top_module(
    input [2:0] in_row,
    output reg [4:0] out_code
    );parameter [4:0] d_0 = 5'b01110; 
parameter [4:0] d_1 = 5'b11001; 
parameter [4:0] d_2 = 5'b10101; 
parameter [4:0] d_3 = 5'b10011; 
parameter [4:0] d_4 = 5'b10001; 


always @ *
begin
	case (in_row)
		3'b000:
			out_code = d_0;
		3'b001:
			out_code = d_1;
		3'b010:
			out_code = d_2;
		3'b011:
			out_code = d_3;
		3'b100:
			out_code = d_4;
		3'b101:
			out_code = d_0;
		default:
			out_code = 5'b0;
	endcase
end

endmodule

