description:
Design a debouncer circuit that stabilizes the input signal from mechanical switches or buttons. This module utilizes a finite state machine with four states to ignore transient fluctuations in the input signal. When the input is pressed (logic high), the circuit counts up to a defined delay; if held stable for the duration, it transitions to an output state of logic high. Conversely, when the input is released (logic low), it similarly counts down to produce a logic low output after the specified delay. The debouncer effectively filters out noise and bounce, ensuring a clean and reliable output signal representative of the actual button state.
module top_module(
  input in,
  output out
);

code:
module top_module(
  input in,
  output out
);reg [1:0] state;
  reg out_reg;
  reg [31:0] count;

  parameter DELAY = 100000; // 10ms delay

  always @(posedge in or negedge in) begin
    if (state == 2'b00 && in == 1'b1) begin
      state <= 2'b01;
      count <= 0;
    end else if (state == 2'b01 && in == 1'b1) begin
      if (count < DELAY) begin
        count <= count + 1;
      end else begin
        state <= 2'b10;
        out_reg <= 1'b1;
      end
    end else if (state == 2'b10 && in == 1'b0) begin
      state <= 2'b11;
      count <= 0;
    end else if (state == 2'b11 && in == 1'b0) begin
      if (count < DELAY) begin
        count <= count + 1;
      end else begin
        state <= 2'b00;
        out_reg <= 1'b0;
      end
    end else begin
      count <= 0;
    end
  end

  assign out = out_reg;

endmodule

module mealy_machine_5 (
  input in,
  input [3:0] state,
  output reg [3:0] next_state,
  output reg out);parameter P=0, Q=1, R=2, S=3;

    assign next_state[P] = (state[R] & ~in) | (state[Q] & in);
    assign next_state[Q] = (state[P] & ~in) | (state[S] & in);
    assign next_state[R] = (state[P] & in) | (state[S] & ~in);
    assign next_state[S] = (state[Q] & ~in) | (state[R] & in);

    assign out = (state[P] & ~in) | state[Q] | (state[S] & in);

endmodule

