Design a score generator that increments a 14-bit score output at a frequency derived from a 50 MHz clock input. The circuit utilizes a counter to generate a lower frequency clock (clk_out) by toggling every 50 million clock cycles, effectively creating a 1 Hz signal. The score is incremented by 1 for every rising edge of this derived clock, thereby enabling systematic score updates suitable for applications such as game scoring or timing systems.
module top_module(
    input clk,
    output reg [13:0] score
);

code:
module top_module(
    input clk,
    output reg [13:0] score
);reg [31:0] counter=1;
    reg temp_clk = 0 ;
    always @ (posedge ( clk ) )
        begin
        if (counter== 50000000 )
            begin
                counter <= 1 ;
                temp_clk <= ~temp_clk ;
            end
             else
                counter <= counter+1;
            end
    assign clk_out = temp_clk ;

    always@(posedge(clk_out))
        begin
            score<=score+1;
        end
endmodule

