module top_module(
    input clk, nreset, WAIT,
    output reg wait_random
);reg [8:0] wait_counter;

    always @(posedge clk or negedge nreset) begin
        if (!nreset) begin
            wait_counter <= 9'b0;
        end else begin
            wait_counter <= wait_counter + 1'b1;
        end
    end

    always @* begin
        if (WAIT) begin
            if (wait_counter[5:0] != 6'b0) begin
                wait_random = 1'b1;
            end else begin
                wait_random = 1'b0;
            end
        end else begin
            wait_random = 1'b0;
        end
    end

endmodule

module encoder_4to2(
    input [3:0] in,
    output [1:0] out,
    output valid);

    assign out = (in[3]) ? 2'b11 :
                 (in[2]) ? 2'b10 :
                 (in[1]) ? 2'b01 : 2'b00;
    assign valid = |in;
endmodule

module comparator_4bit (a, b, eq);
   input [3:0] a, b;
   output eq;

   assign eq = (a == b);
endmodule

module parity_generator(
    input [7:0] data,
    output reg parity
);

always @(*) begin
    parity = data[0] ^ data[1] ^ data[2] ^ data[3] ^ data[4] ^ data[5] ^ data[6] ^ data[7];
end

endmodule

