    if (load) begin
        // load data on next rising edge of clock
        shift_reg <= data_in;
    end else begin
        // shift data
        shift_reg <= {shift_reg[2:0], shift_reg[3]};
    end
end

// output data
assign data_out = shift_reg;

endmodule

