description:
Design a 7-segment display driver that takes a 4-bit binary input (iDIG) representing a decimal digit (0-9) or a hexadecimal character (A-F) and outputs the corresponding 7-segment encoding (oSEG) to illuminate the appropriate segments. The module also sets the decimal point output (oSEG_DP) to always be HIGH, indicating that the decimal point is active. The implemented look-up table provides the necessary segment configurations for visual representation on a 7-segment display.
module top_module(
    output reg [6:0]    oSEG,
    output reg          oSEG_DP,
    input [3:0]         iDIG
);

code:
module top_module(
    output reg [6:0]    oSEG,
    output reg          oSEG_DP,
    input [3:0]         iDIG
);always @(iDIG)
begin
    case(iDIG)
    4'h1: oSEG = 7'b1111001;    
    4'h2: oSEG = 7'b0100100;    
    4'h3: oSEG = 7'b0110000;    
    4'h4: oSEG = 7'b0011001;    
    4'h5: oSEG = 7'b0010010;    
    4'h6: oSEG = 7'b0000010;    
    4'h7: oSEG = 7'b1111000;    
    4'h8: oSEG = 7'b0000000;    
    4'h9: oSEG = 7'b0011000;    
    4'ha: oSEG = 7'b0001000;
    4'hb: oSEG = 7'b0000011;
    4'hc: oSEG = 7'b1000110;
    4'hd: oSEG = 7'b0100001;
    4'he: oSEG = 7'b0000110;
    4'hf: oSEG = 7'b0001110;
    4'h0: oSEG = 7'b1000000;
    endcase
end

always @(iDIG)
begin
    oSEG_DP = 1;
end

endmodule

